EXPLAIN ANALYZE SELECT m.* FROM messages m WHERE m.room_id IN (911000,911001,911002,911003,911004,911005,911006,911007,911008,911009,911010,911011,911012,911013,911014,911015,911016,911017,911018,911019,911020,911021,911022,911023,911024,911025,911026,911027,911028,911029,911030,911031,911032,911033,911034,911035,911036,911037,911038,911039,911040,911041,911042,911043,911044,911045,911046,911047,911048,911049) AND m.sequence=(SELECT MAX(x.sequence) FROM messages x WHERE x.room_id=m.room_id);
EXPLAIN ANALYZE SELECT m.* FROM messages m JOIN (SELECT room_id,MAX(sequence) AS latest_sequence FROM messages WHERE room_id IN (911000,911001,911002,911003,911004,911005,911006,911007,911008,911009,911010,911011,911012,911013,911014,911015,911016,911017,911018,911019,911020,911021,911022,911023,911024,911025,911026,911027,911028,911029,911030,911031,911032,911033,911034,911035,911036,911037,911038,911039,911040,911041,911042,911043,911044,911045,911046,911047,911048,911049) GROUP BY room_id) latest ON m.room_id=latest.room_id AND m.sequence=latest.latest_sequence;
